Examples.Python:
import boto3

s3 = boto3.client('s3')

# SNAPSHOT
try:
    lock_config = s3.get_object_lock_configuration(Bucket=source_bucket)['ObjectLockConfiguration']
    if lock_config.get('ObjectLockEnabled') == 'Enabled':
        print('Source bucket already has Object Lock'); exit(0)
except s3.exceptions.ClientError as e:
    if 'ObjectLockConfigurationNotFoundError' in str(e):
        pass  # Expected — bucket needs remediation
    else:
        raise

# FIX-1: Create new bucket with Object Lock
try:
    create_params = {'Bucket': dest_bucket, 'ObjectLockEnabledForBucket': True}
    if region != 'us-east-1':
        create_params['CreateBucketConfiguration'] = {'LocationConstraint': region}
    s3.create_bucket(**create_params)
except s3.exceptions.BucketAlreadyOwnedByYou:
    pass  # Check if Object Lock is enabled
except s3.exceptions.BucketAlreadyExists:
    raise RuntimeError(f'Bucket name {dest_bucket} is taken globally')

# FIX-2: Configure retention
retention_mode = retention_mode or 'GOVERNANCE'
retention_days = retention_days or 365
s3.put_object_lock_configuration(
    Bucket=dest_bucket,
    ObjectLockConfiguration={
        'ObjectLockEnabled': 'Enabled',
        'Rule': {'DefaultRetention': {'Mode': retention_mode, 'Days': retention_days}}
    }
)

# FIX-3: Migrate objects
paginator = s3.get_paginator('list_objects_v2')
for page in paginator.paginate(Bucket=source_bucket):
    for obj in page.get('Contents', []):
        copy_source = {'Bucket': source_bucket, 'Key': obj['Key']}
        try:
            s3.copy_object(CopySource=copy_source, Bucket=dest_bucket, Key=obj['Key'])
        except s3.exceptions.ClientError as e:
            print(f"Failed to copy {obj['Key']}: {e}")  # Log and continue

# VERIFY
verify_lock = s3.get_object_lock_configuration(Bucket=dest_bucket)['ObjectLockConfiguration']
assert verify_lock['ObjectLockEnabled'] == 'Enabled'
assert verify_lock['Rule']['DefaultRetention']['Mode'] == retention_mode
assert verify_lock['Rule']['DefaultRetention']['Days'] == retention_days
# Verify source still exists
s3.head_bucket(Bucket=source_bucket)
print(f'SUCCESS: Object Lock enabled on {dest_bucket} with {retention_mode} mode, {retention_days} day retention')

Examples.Terraform:
# Object Lock must be enabled at bucket creation — cannot be added to existing bucket.
resource "aws_s3_bucket" "locked" {
  bucket              = var.destination_bucket_name
  object_lock_enabled = true
}

resource "aws_s3_bucket_object_lock_configuration" "retention" {
  bucket = aws_s3_bucket.locked.id

  rule {
    default_retention {
      mode = var.retention_mode  # "GOVERNANCE" or "COMPLIANCE"
      days = var.retention_days  # e.g., 365
    }
  }
}

resource "aws_s3_bucket_versioning" "locked" {
  bucket = aws_s3_bucket.locked.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Data migration cannot be managed by Terraform declaratively.
# Use a null_resource with local-exec to run aws s3 sync:
resource "null_resource" "migrate" {
  depends_on = [aws_s3_bucket_object_lock_configuration.retention]
  provisioner "local-exec" {
    command = "aws s3 sync s3://${var.source_bucket_name} s3://${var.destination_bucket_name}"
  }
}

# DO NOT destroy the source bucket — preserve as rollback target.

Examples.Cdk:
import * as s3 from 'aws-cdk-lib/aws-s3';

// Create new bucket with Object Lock enabled
const lockedBucket = new s3.Bucket(this, 'LockedBucket', {
  bucketName: destinationBucketName,
  objectLockEnabled: true,
  versioned: true,  // Required for Object Lock
  objectLockDefaultRetention: s3.ObjectLockRetention.governance(
    cdk.Duration.days(365)
  ),
  // For Compliance mode:
  // objectLockDefaultRetention: s3.ObjectLockRetention.compliance(cdk.Duration.days(365)),
});

// Data migration must be handled outside CDK:
// Use a Custom Resource (Lambda) that runs S3 sync/copy
// or trigger S3 Batch Operations job.
// The source bucket should NOT be deleted from the CDK stack.

// WARNING: Compliance mode Object Lock is IRREVERSIBLE.
// Objects cannot be deleted until retention expires.
